package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.SortOrder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DefaultKeyedValues_removeValue_TriageGen1Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_RemoveFirstElement() {
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);
        keyedValues.addValue("C", 3.0);

        keyedValues.removeValue(0);

        assertEquals(2, keyedValues.getItemCount());
        assertEquals("B", keyedValues.getKey(0));
        assertEquals(2.0, keyedValues.getValue(0).doubleValue(), 0.001);
        assertEquals("C", keyedValues.getKey(1));
        assertEquals(3.0, keyedValues.getValue(1).doubleValue(), 0.001);
    }










}

